import {startI18n} from './assets/site-i18n.js';
import {isBookPath,mountBook,stopBook} from './assets/book-player.js';
import {showBuilder} from './assets/builder.js';
import {mountThreeKingdoms,isThreeKingdomsPath} from './assets/three-kingdoms.js';
import {createPayments} from './assets/payments.js';
import {createAccount} from './assets/account.js';
const [data,reference,community]=await Promise.all([
 fetch('/data.json').then(r=>{if(!r.ok)throw Error('Catalogue unavailable');return r.json();}),
 import('./assets/reference.js'),
 import('./assets/community.js'),
]).catch(error=>{
 const boot=document.querySelector('#boot-screen');
 if(boot)boot.innerHTML='<p>Unable to load stories.</p><button onclick="location.reload()">Try again</button>';
 throw error;
});
let interaction, interactionRequest, routeVersion=0;
const loadInteraction=()=>interactionRequest||(interactionRequest=import('./assets/interaction.js').then(module=>interaction=module).catch(error=>{interactionRequest=null;throw error;}));
for(const story of reference.extraStories)if(!data.some(d=>d.id===story.id))data.push(story);
const $=s=>document.querySelector(s),main=$('#main'),modal=$('#modal');
const account=createAccount({changed:reset=>{if(reset){favorites=read('ooc-favorites',[]);history=read('ooc-history',[]);custom=read('ooc-custom',[]);if(account.user&&!read('ooc-onboarding-complete',false)&&!location.pathname.startsWith('/onboarding/'))navigate('/onboarding/1');else render();}else paintAccount();},notify:toast});
const payments=createPayments({account,show,modal,notify:toast});
const read=(k,f)=>account.read(k,f),save=(k,v)=>account.save(k,v);
let favorites=read('ooc-favorites',[]),history=read('ooc-history',[]),custom=read('ooc-custom',[]),slide=0,category='Main',timer;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={Search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',Story:'<path d="M4 3h12v18H4zM8 7h5M8 11h5M8 15h5M18 6h2v15"/>',Character:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>','My Titles':'<path d="M5 4h14v18l-7-4-7 4z"/>',Credits:'<path d="m12 2 2 7 7 3-7 2-2 8-2-8-7-2 7-3z"/>'};
const nav=[['Search','/search'],['Story','/'],['Character','/character'],['My Titles','/my-title'],['Credits','/credit']];
function navigate(url){if(url.split('?')[0]==='/search'&&location.pathname!=='/search'){reference.openSearch({navigate,read,save},new URLSearchParams(url.split('?')[1]||'').get('q')||'');return;}if(location.pathname+location.search===url)return;if(modal.open)modal.close();window.history.replaceState({...window.history.state,scroll:[window.scrollX||0,window.scrollY||0]},'');window.history.pushState({storydateNavigation:true,from:location.pathname+location.search},'',url);render();window.scrollTo(0,0)}
document.addEventListener('click',e=>{const a=e.target.closest('a');if(!e.defaultPrevented&&e.button===0&&a&&a.getAttribute('href')?.startsWith('/')&&!a.getAttribute('href').startsWith('//')&&!a.hasAttribute('download')&&(!a.target||a.target==='_self')&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&!e.altKey){e.preventDefault();const url=a.getAttribute('href');if(!a.hasAttribute('data-full-info')&&reference.preview(url,{navigate,read,save:(key,value)=>{save(key,value);if(key==='ooc-favorites')favorites=value;}}))return;navigate(url)}});
window.addEventListener('popstate',event=>{if(modal.open)modal.close();render();const scroll=event.state?.scroll||[0,0];window.requestAnimationFrame?.(()=>window.scrollTo(...scroll));});
document.addEventListener('pointerover',event=>{if(event.target.closest('[data-play],a[href^="/play/"],a[href^="/onboarding/"]'))void loadInteraction().catch(()=>{});},{passive:true});
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',2800)}
function show(html){modal.innerHTML='<button class="close" aria-label="Close dialog">×</button>'+html;modal.showModal();modal.querySelector('.close').onclick=()=>modal.close()}
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
const footer=()=>`<footer class="footer"><div><strong>Explore</strong><a href="/">Story</a><a href="/character">Character</a><a href="/credit">Credits</a><a href="/my-title">My titles</a></div><div><strong>Support</strong><a href="/support">Contact &amp; Support</a><a href="/terms">Terms of Service</a><a href="/privacy">Privacy Policy</a></div><p>© 2026 StoryDate</p></footer>`;
function card(d,rank){return `<a class="card" href="/story/${esc(d.id)}"><div class="cover"><img src="${esc(/^(https?:|data:)/.test(d.image)?d.image:'/'+d.image)}" alt="${esc(d.title)}" loading="lazy">${rank?`<span class="rank">${rank}</span>`:''}${d.original?'<span class="original">✱ ORIGINAL</span>':''}</div><h3>${esc(d.title)}</h3><div class="meta">${esc(d.plays)} · ${esc(d.author)}</div></a>`}
function section(title,items,rank=true){return `<section class="section"><div class="section-header"><h2>${title}</h2><a href="/collection?name=${encodeURIComponent(title)}">View All ›</a></div><div class="rail">${items.map((d,i)=>card(d,rank?i+1:0)).join('')}</div></section>`}
const categories=['Main','New Ranking','Rankings','Today','Fantasy','Romance','Sci-Fi','History','Girls Love','Horror','Oriental Fantasy','Slice of Life','Fan Fiction','Utility','Boys Love','Others'];
const features=[data[6],data[4],data[2],data[10],data[7],data[27]];
const descriptions=['Hunt or be hunted. The answer is obvious.','The #1 hero just exposed your secret relationship.','| 🖼️ 150+ img | ♀️ 12 Characters | ♂️ 8 Characters','"Failed Knight" was a lifelong insulting label.','Received a confession as a Dare Game penalty.','The chaotic 1st Knight Order! Never a quiet day!'];
function hero(){const d=features[slide];return `<div class="hero-copy"><h1>${esc(d.title)}</h1><p>${esc(descriptions[slide])}</p><a class="primary" href="/story/${d.id}">Explore</a></div><a href="/story/${d.id}"><img class="hero-image" src="${/^(https?:|data:)/.test(d.image)?d.image:'/'+d.image}" alt="${esc(d.title)}"></a><div class="dots">${features.map((_,i)=>`<button data-slide="${i}" class="${i===slide?'active':''}" aria-label="Slide ${i+1}"></button>`).join('')}</div><div class="hero-controls"><button class="round" data-step="-1" aria-label="Previous slide">‹</button><span>${slide+1} / 6</span><button class="round" data-step="1" aria-label="Next slide">›</button></div>`}
function home(){main.innerHTML=`<div class="notice"><span>Notifications</span><button data-action="notice">Title Publishing Bug Resolved</button><span style="margin-left:auto">›</span></div><section class="hero" aria-label="Featured stories">${hero()}</section><div class="categories" aria-label="Story categories">${categories.map(c=>`<button data-category="${c}" class="${category===c?'active':''}">${c}</button>`).join('')}</div><div id="catalog"></div>${footer()}`;catalog()}
function catalog(){if(category==='Main'){$('#catalog').innerHTML=section('Top Ranked',data.slice(0,20))+`<a class="banner" href="/story/${data[19].id}"><div><h2>Dice of Fate: A reverse Isekai</h2><p>First AIRPG on OOC</p></div><span class="primary">Explore →</span></a>`+section('OOC Originals',data.filter(d=>d.original),false)+section('Trending Now',[data[5],data[10],data[27],data[2],data[9]])+section('Trending New Creators',data.filter(d=>!d.original),false)+`<section class="section"><h2>Tags</h2><div class="tags" style="margin-top:20px">${['Fantasy','Romance','Adventure','Action','Isekai','Magic','Slice of Life','Comedy','Horror','Simulation','Thriller'].map(t=>`<button data-tag="${t}">#${t.replaceAll(' ','')}</button>`).join('')}</div></section>`+section('New from certified creators',data.slice(12,20),false)}else{let items=['New Ranking','Today'].includes(category)?data.slice().reverse():category==='Rankings'?data:data.filter(d=>d.genre===category);$('#catalog').innerHTML=`<section class="section"><h2 class="page-title">${esc(category)}</h2>${items.length?`<div class="grid">${items.map((d,i)=>card(d,category==='Rankings'?i+1:0)).join('')}</div>`:'<div class="empty">No stories in this category yet.<br><br><button class="primary" data-category="Main">Explore all stories</button></div>'}</section>`}}
function results(items){return items.length?items.map(d=>card(d)).join(''):'<div class="empty">No matching stories found. Try another title or creator.</div>'}
function search(){main.innerHTML=`<h1 class="page-title">Search</h1><label class="searchbox"><span>⌕</span><input type="search" id="query" placeholder="Search stories, characters, creators" aria-label="Search stories" autocomplete="off"></label><div class="tags">${['Fantasy','Romance','Academy','OOC'].map(t=>`<button data-query="${t}">${t}</button>`).join('')}</div><h2 class="page-title" id="result-title">Popular stories</h2><div class="grid" id="results">${results(data)}</div>${footer()}`;$('#query').oninput=()=>{const q=$('#query').value.toLowerCase().trim(),items=data.filter(d=>`${d.title} ${d.author} ${d.genre}`.toLowerCase().includes(q));$('#results').innerHTML=results(items);$('#result-title').textContent=q?`${items.length} results`:'Popular stories'}}
function detail(id){const d=data.find(d=>d.id===id);if(!d){main.innerHTML='<h1 class="page-title">Story not found</h1><a href="/">Return home</a>';return}const description=d===data[0]?'An imperial academy of sword and sorcery':features.includes(d)?descriptions[features.indexOf(d)]:`Step into the world of ${d.title}.`;
main.innerHTML=`<div class="detail"><button class="back" data-action="back">‹ Story Information</button><div class="detail-top"><img class="detail-cover" src="${/^(https?:|data:)/.test(d.image)?d.image:'/'+d.image}" alt="${esc(d.title)}"><div class="detail-info"><h1>${esc(d.title)}</h1><p>${esc(d.author)} ${d.original?'✱':''}</p><div class="detail-tags"><span class="tag">150 Images</span><span class="tag">Creator Custom Prompt</span><span class="tag">${esc(d.genre)}</span></div><p>${esc(description)}</p><div class="tags"><button data-tag="${d.genre}">#${d.genre}</button><button data-tag="Academy">#academy</button><button data-tag="Fantasy">#fantasy</button></div><div class="stats"><span>◉ ${d.plays}</span><span>♡ ${d===data[0]?'85.7K':'1.2K'}</span><span>☏ ${d===data[0]?'103.5K':'348'}</span></div><div class="detail-actions"><button class="primary" data-play="${id}">New Play</button><button class="secondary" data-favorite="${id}" aria-label="Bookmark story">${favorites.includes(id)?'♥':'♡'}</button></div></div></div><h2>Story Description</h2><p>${d===data[0]?'An imperial academy where sword and magic intertwine':esc(description)}</p><details><summary>Settings</summary><p>Choose your own path through this world. Your choices shape the adventure.</p><small class="demo">Demo content for this replica.</small></details><details><summary>Avatar Settings</summary><p>Give your protagonist a name.</p><input id="avatar" aria-label="Avatar name" placeholder="Your name" value="${esc(read('ooc-avatar',''))}"><button class="secondary" data-action="save-avatar">Save</button></details><details><summary>Starting Scenarios</summary><p>Arrival at the academy</p><button class="primary" data-play="${id}">Start this scenario</button></details><div class="tabs"><button class="active" data-preview="characters">Character Preview</button><button data-preview="prologue">Prologue Preview</button></div><div class="preview" id="preview">${characterPreview(d)}</div><h2>Last Update</h2><p class="meta">10/14/2026</p><h2>Comments</h2><small class="demo">Local demo comments</small><form id="comment-form"><input name="comment" placeholder="Leave a comment" aria-label="Your comment" required maxlength="500"><button class="secondary">Post</button></form><div id="comments"></div>${footer()}</div>`;
const comments=read('ooc-comments-'+id,[]);const renderComments=()=>$('#comments').innerHTML=comments.map(c=>`<div class="preview"><b>You</b><p>${esc(c)}</p></div>`).join('');renderComments();$('#comment-form').onsubmit=e=>{e.preventDefault();const input=e.target.elements.comment;const v=input.value.trim();if(!v)return;comments.unshift(v);save('ooc-comments-'+id,comments);input.value='';renderComments()};}
function characterPreview(d){return `<div class="characters">${['Lucia','Isabel','Rena','Chloe'].map((n,i)=>`<div><img src="/assets/character-${i}.webp" alt="${n}" onerror="this.src='/assets/cover-0.webp'"><p>${n}</p></div>`).join('')}</div><small class="demo">Observed character names; demo artwork uses story covers because original character assets could not be downloaded.</small>`}
function collection(){const name=new URLSearchParams(location.search).get('name')||'Top Ranked';const items=name==='OOC Originals'?data.filter(d=>d.original):name==='Trending New Creators'?data.filter(d=>!d.original):data;main.innerHTML=`<a class="back" href="/">‹ Back</a><h1 class="page-title">${esc(name)}</h1><div class="grid">${results(items)}</div>${footer()}`}
function titles(){main.innerHTML=`<h1 class="page-title">My Titles</h1><div class="tabs"><button class="active" data-library="saved">Bookmarks</button><button data-library="history">History</button><button data-library="created">Created</button></div><div id="library" style="margin-top:28px"></div><button class="primary" data-action="create" style="margin-top:25px">+ Create a story</button>${footer()}`;library('saved')}
function library(type){const items=type==='history'?history:type==='saved'?favorites:[];$('#library').innerHTML=type==='created'?custom.map(c=>`<div class="preview"><h2>${esc(c.title)}</h2><p>${esc(c.description)}</p><small class="demo">Local draft</small></div>`).join('')||'<div class="empty">Your story starts here. Create your first draft.</div>':items.length?`<div class="grid">${results(items.map(id=>data.find(d=>d.id===id)).filter(Boolean))}</div>`:'<div class="empty">Your library is empty.<br><br><a class="primary" href="/">Explore stories</a></div>'}
function credits(){reference.mountShell('<div id="wallet-view"></div>',{navigate,show,...account.scope(),categories,data},'credit');payments.mount($('#wallet-view'));}
function chat(id){const d=data.find(d=>d.id===id);if(!d){navigate('/');return}history=[id,...history.filter(x=>x!==id)];save('ooc-history',history);const messages=read('ooc-chat-'+id,[{role:'story',text:`The gates open before you. Welcome to ${d.title}. A new adventure awaits. What will you do?`}]);main.innerHTML=`<div class="chat"><div class="chat-header"><a href="/story/${id}">‹ ${esc(d.title)}</a><small class="demo">Interactive local story demo · responses are scripted, not AI generated.</small></div><div class="chat-body" id="chat-body"></div><form class="composer" id="chat-form"><input name="message" aria-label="Your action" placeholder="What will you do next?" maxlength="1000" required><button class="primary">Send ↑</button></form><button class="secondary" data-action="reset-chat" style="margin-top:20px">Restart story</button></div>`;const showMessages=()=>$('#chat-body').innerHTML=messages.map(m=>`<div class="message ${m.role==='user'?'user':''}">${esc(m.text)}</div>`).join('');showMessages();$('#chat-form').onsubmit=e=>{e.preventDefault();const input=e.target.elements.message,v=input.value.trim();if(!v)return;messages.push({role:'user',text:v});const n=messages.filter(m=>m.role==='user').length;const replies=[`A young student turns toward ${read('ooc-avatar','you')||'you'}. “You must be new here. The entrance trial is about to begin. Will you follow me to the courtyard, or explore the library?”`,'The corridor grows quiet. Beyond the doors, you hear the clash of training swords. A mysterious letter lies on the desk, sealed with the academy crest. Do you open it?','The letter reads: “Meet me at the old tower before sunset.” You pocket it as footsteps approach. Your next choice will determine who you can trust.','A bell rings across the academy. Your companion smiles. “Our adventure has only just begun.” Choose to train, explore, or speak with your companion.'];messages.push({role:'story',text:replies[(n-1)%replies.length]});save('ooc-chat-'+id,messages);input.value='';showMessages();$('#chat-body').lastElementChild.scrollIntoView({block:'nearest',behavior:'smooth'})};}
function preferences(){let choice=read('ooc-preference','All');show(`<h2>Content Preference</h2><p>Select the type of content you'd like to see.</p><div class="choices">${['All','Male','Female'].map(x=>`<button data-choice="${x}" class="${choice===x?'active':''}">${x}</button>`).join('')}</div><small class="demo">This demo stores your preference locally.</small><button class="primary" id="confirm-preference">Confirm</button>`);modal.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{choice=b.dataset.choice;modal.querySelectorAll('[data-choice]').forEach(x=>x.classList.toggle('active',x===b))});$('#confirm-preference').onclick=()=>{save('ooc-preference',choice);modal.close();toast('Content preference saved')}}
function render(){renderPage();paintAccount();document.body.removeAttribute('data-booting');$('#boot-screen')?.remove();}
function renderPage(){stopBook();clearInterval(window.carousel);const path=location.pathname,version=++routeVersion;
 if(isBookPath(path)){interaction?.show('/book-campaign',{navigate,show,...account.scope(),categories,data});void mountBook(path,{reference,helpers:{navigate,show,...account.scope(),categories,data}});return;}
 if(path==='/credit'){interaction?.show(path,{navigate,show,...account.scope(),categories,data});credits();return;}
 if(isThreeKingdomsPath(path)){interaction?.show('/three-kingdoms',{navigate,show,...account.scope(),categories,data});mountThreeKingdoms(path,{reference,account,helpers:{navigate,show,...account.scope(),categories,data}});return;}
 if(path.startsWith('/play/')||path.startsWith('/onboarding/')||/^\/(story|character)\/[^/]+\/episode\//.test(path)){
  if(interaction){interaction.show(path,{navigate,show,...account.scope(),categories,data});return;}
  reference.mountShell('<div class="route-loading" role="status">Loading your story…</div>',{navigate,show,...account.scope(),categories,data},'loading');
  void loadInteraction().then(module=>{if(version!==routeVersion)return;module.show(path,{navigate,show,...account.scope(),categories,data});paintAccount();}).catch(()=>{if(version===routeVersion)show('<h2>Unable to load this story</h2><p>Please refresh and try again.</p>');});
  return;
 }
 interaction?.show(path,{navigate,show,...account.scope(),categories,data});if(showBuilder(path,{navigate,show,...account.scope(),categories,data,account}))return;if(community.show(path,{navigate,show,...account.scope(),categories,data,account,repaint:paintAccount}))return;if(reference.show(path,{navigate,show,...account.scope(),categories,data}))return;$('#nav').innerHTML=nav.map(([label,url])=>`<a href="${url}" class="${path===url?'active':''}"><svg viewBox="0 0 24 24">${icons[label]}</svg>${label}</a>`).join('');if(path==='/'){home();if(!matchMedia('(prefers-reduced-motion: reduce)').matches)window.carousel=setInterval(()=>{if(document.hidden||modal.open)return;slide=(slide+1)%6;const h=$('.hero');if(h)h.innerHTML=hero()},6500)}else if(path==='/search')search();else if(path.startsWith('/story/'))detail(path.split('/')[2]);else if(path.startsWith('/play/'))chat(path.split('/')[2]);else if(path==='/collection')collection();else if(path==='/my-title'||path==='/history'){titles();if(path==='/history')library('history')}else if(isBookPath(path)){interaction?.show('/book-campaign',{navigate,show,...account.scope(),categories,data});void mountBook(path,{reference,helpers:{navigate,show,...account.scope(),categories,data}});return;}
 if(path==='/credit')credits();else if(path==='/character'){main.innerHTML=`<h1 class="page-title">Character</h1><small class="demo">Lumencia Academy · character preview demo</small><div class="characters">${['Lucia','Isabel','Rena','Chloe'].map((n,i)=>`<a href="/story/${data[0].id}"><img src="/assets/character-${i}.webp" alt="${n}"><h3>${n}</h3><p class="meta">Lumencia Academy</p></a>`).join('')}</div>${footer()}`}else{main.innerHTML='<h1 class="page-title">Page not found</h1><a class="primary" href="/">Return home</a>'}document.title=path.startsWith('/story/')?`${data.find(d=>d.id===path.split('/')[2])?.title||'Story'} · Storylove`:'Storylove · Interactive stories'}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.slide!==undefined||d.step){slide=d.step?(slide+Number(d.step)+6)%6:Number(d.slide);$('.hero').innerHTML=hero()}if(d.category){category=d.category;$('.categories')?.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x.dataset.category===category));catalog()}if(d.tag){navigate('/search');$('#query').value=d.tag;$('#query').dispatchEvent(new Event('input'))}if(d.query){$('#query').value=d.query;$('#query').dispatchEvent(new Event('input'))}if(d.favorite){favorites=favorites.includes(d.favorite)?favorites.filter(x=>x!==d.favorite):[...favorites,d.favorite];save('ooc-favorites',favorites);if(d.referenceFavorite){b.style.color=favorites.includes(d.favorite)?'#e0ff2e':'';b.setAttribute('aria-pressed',String(favorites.includes(d.favorite)))}else b.textContent=favorites.includes(d.favorite)?'♥':'♡';toast(favorites.includes(d.favorite)?'Added to bookmarks':'Removed from bookmarks')}if(d.play)navigate('/play/'+d.play);if(d.library){$('.tabs').querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));library(d.library)}if(d.preview){$('.tabs').querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));$('#preview').innerHTML=d.preview==='characters'?characterPreview(data.find(x=>x.id===location.pathname.split('/')[2])):'The academy gates loom before you. Beyond them lies a world of sword and sorcery, and a future waiting to be written.<small class="demo">Replica prologue demo.</small>'}if(d.action==='back')navigate('/');if(d.action==='preferences')preferences();if(d.action==='save-avatar'){save('ooc-avatar',$('#avatar').value.trim());toast('Avatar saved')}if(d.action==='login')account.login(d.provider||(/Apple/.test(b.textContent)?'apple':'google'));if(d.action==='logout')account.logout();if(d.action==='account-profile'){if(account.user)navigate('/profile');else account.login();}if(d.action==='retry-sync')account.flush();if(d.action==='close')modal.close();if(d.action==='notice')show('<h2>Title Publishing Bug Resolved</h2><p>The publishing issue has been resolved.</p><small class="demo">Reproduced notification · this is a local demo.</small><button class="primary" data-action="close">Got it</button>');if(d.action==='about'||d.action==='support')show('<h2>OOC Interface Replica</h2><p>Built from observations of the public OOC website. Search, bookmarks, drafts, comments, and story demos run locally in your browser. Account data uses Firebase when configured. Credits checkout uses Stripe when configured. AI replies use the configured independent server; Demo mode remains available.</p><button class="primary" data-action="close">Close</button>');if(d.action==='credit-info')navigate('/credit');if(d.action==='reset-chat'){save('ooc-chat-'+location.pathname.split('/')[2],null);render()}if(d.action==='create'){show('<h2>Create a story</h2><form id="create-form"><input name="title" placeholder="Story title" aria-label="Story title" required maxlength="120"><textarea name="description" placeholder="Describe your world" aria-label="Story description" rows="4" required maxlength="2000" style="width:100%"></textarea><small class="demo">Saved as a local draft.</small><button class="primary">Save draft</button></form>');$('#create-form').onsubmit=e=>{e.preventDefault();const f=e.target.elements;if(!f.title.value.trim()||!f.description.value.trim())return;custom.push({title:f.title.value.trim(),description:f.description.value.trim()});save('ooc-custom',custom);modal.close();titles();library('created');toast('Draft saved')}}});
startI18n();render();account.init();

function paintAccount(){
 payments.sync();
 reference.syncAccount(account);
 // Public navigation remains usable while credentials and cloud state restore.
 for(const el of document.querySelectorAll('body > aside, #main, #precision-view, #modal'))el.inert=false;

 document.querySelectorAll('[data-action="login"]').forEach(b=>{const provider=b.dataset.provider||(/Apple/.test(b.textContent)?'apple':'google');b.dataset.provider=provider;b.hidden=Boolean(account.user)||(provider==='apple'&&!account.providers.apple);b.disabled=account.busy;});
 let bar=document.querySelector('#account-status');if(!bar){bar=document.createElement('div');bar.id='account-status';bar.setAttribute('role','status');document.body.append(bar);}
 bar.innerHTML=account.user?`<button data-action="account-profile">${esc(account.read('ooc-profile',{}).name||account.user.displayName||'My account')}</button><button data-action="logout" ${account.busy?'disabled':''}>Sign out</button>${account.syncError?`<span>${esc(account.syncError)}</span><button data-action="retry-sync">Retry sync</button>`:''}`:account.busy?'Restoring account…':account.error?`<span>${esc(account.error)}</span>`:`<button data-action="login" data-provider="google">Continue with Google</button>${account.providers.apple?'<button data-action="login" data-provider="apple">Continue with Apple</button>':''}`;
}
